const metricCoverage={};
function updateMetricCoverage() {
  const projects=rows.map((_,index)=>project(index));
  metricCoverage.GRID=summarizeCoverage(projects,gridDistance);metricCoverage.SUB=summarizeCoverage(projects,substation);
  runtimeEvidence.metricCoverage=metricCoverage;
  const note=document.getElementById('gridDistanceNote');if(!note)return;
  const describe=label=>{const c=metricCoverage[label];return c.available?label+' '+c.measured.toLocaleString('en-GB')+'/'+c.total.toLocaleString('en-GB'):label+' unavailable';};
  note.textContent='Main register coverage ? '+describe('GRID')+' ? '+describe('SUB')+' ? '+metricCoverage.GRID.withoutCoordinates+' without usable coordinates ? straight-line mapped observations, not routes or headroom';
  if(runtimeEvidence.gridCoverageFallback||runtimeEvidence.subCoverageFallback)note.textContent+=' ? verified baseline used where available';
  note.title='Counts are intersections with the main register, not all keys in the source indexes. GRID source keys: '+metricCoverage.GRID.sourceKeys+'; SUB source keys: '+metricCoverage.SUB.sourceKeys+'. Nearest mapped infrastructure may not be the nearest actual infrastructure.';
  note.setAttribute('role','status');
}

